// AtIoJamInfoHeader, AtIoFastAlignedJamHeader, AtIoFastRawJamHeader — recovered methods (partial).
// Original address clusters 0x0007F120-0x0007FFC4 and 0x0007D170-0x0007D1DF.
// Verification status per function: config/functions.toml, docs/PROGRESS.md (generated by tools/verify.py).
#include "at/AtIoJam.h"
#include "AtIoJamCommon.h"

const char* AtIoJamInfoHeader::s_tokens[4] = {"JAM1", "JAM2", "FSTA", "FSTR"};

AtIoJamInfoHeader::AtIoJamInfoHeader() {
    Clear();
}

void AtIoJamInfoHeader::Clear() {
    m_token = 0;
    m_unknown04 = 0;
    m_headerSize = 0;
    unsigned int* label = (unsigned int*)m_label;
    label[0] = 0;
    label[1] = 0;
    label[2] = 0;
    label[3] = 0;
}

void AtIoJamInfoHeader::Init(const char* raw) {
    if (m_token != 0) {
        Clear();
    }
    if (strncmp(raw, s_tokens[0], 4) == 0) {
        m_token = kJam1;
    } else if (strncmp(raw, s_tokens[1], 4) == 0) {
        m_token = kJam2;
    } else if (strncmp(raw, s_tokens[2], 4) == 0) {
        m_token = kFsta;
    } else if (strncmp(raw, s_tokens[3], 4) == 0) {
        m_token = kFstr;
    } else {
        AtFatal("AtIoJamInfoHeader::vInit:  expected a valid Jam token!\n", 0, 0, 0);
    }
    const unsigned char* p = (const unsigned char*)raw;
    m_unknown04 = AtReadU32(p + 4);
    m_headerSize = AtReadU32(p + 8);
    for (int i = 0; i < 15; i++) {
        m_label[i] = raw[12 + i];
    }
    m_nameCount = AtReadU16(p + 0x1C);
    m_extensionCount = p[0x1E];
}

AtIoFastAlignedJamHeader::AtIoFastAlignedJamHeader() {
    m_fs = 0;
    m_files = 0;
    m_buffer = 0;
    m_root = 0;
    m_rootFiles = 0;
    m_rootDirs = 0;
    m_swappedFields = 0;
}

void AtIoFastAlignedJamHeader::Reset() {
    m_fs = 0;
    m_files = 0;
    m_buffer = 0;
    m_root = 0;
    m_rootFiles = 0;
    m_rootDirs = 0;
    m_swappedFields = 0;
}

AtIoFastRawJamHeader::AtIoFastRawJamHeader() {
    AtIoFastAlignedJamHeader::Reset();
    m_swappedFields = 1;
}

void AtIoFastRawJamHeader::Reset() {
    AtIoFastAlignedJamHeader::Reset();
    m_swappedFields = 1;
}

// Original behaviour preserved, all visible through `entry` and `found`:
//  * `entry` is not rewound after a component misses, so the next component continues from where the scan stopped;
//  * `found` describes the last component only, so a missing middle component is not an error by itself.
const unsigned char* AtIoFastAlignedJamHeader::FindDirectory(const char* path, unsigned int* dirs, unsigned int* files) {
    if (path == 0 || *path == 0) {
        *dirs = m_rootDirs;
        *files = m_rootFiles;
        return m_root;
    }
    char copy[256];
    strcpy(copy, path);
    unsigned int length = strlen(path);
    for (unsigned int i = 0; i < length; i++) {
        copy[i] = (char)toupper(copy[i]);
    }
    unsigned int foundFiles = m_rootFiles;
    const unsigned char* entry = m_root;
    unsigned int count = m_rootDirs;
    char* cursor = copy;
    int found = 0;
    if (strlen(cursor) == 0) {
        return 0;
    }
    do {
        char* separator = strchr(cursor, '\\');
        if (separator) {
            *separator = 0;
        }
        int name = m_table.FindName(cursor);
        if (name < 0) {
            return 0;
        }
        if (separator) {
            cursor = separator + 1;
        } else {
            *cursor = 0;
        }
        found = 0;
        for (unsigned int i = 0; i < count; i++) {
            unsigned int word = AtReadU32(entry);
            unsigned int offset = AtReadU32(entry + 4);
            entry += 8;
            if ((int)(word & 0xFFF) == name) {
                found = 1;
                if (m_swappedFields) {
                    count = word >> 21;
                    foundFiles = (word & 0x1FF000) >> 12;
                } else {
                    count = (word & 0x1FF000) >> 12;
                    foundFiles = word >> 21;
                }
                entry = m_buffer + offset;
                break;
            }
        }
    } while (strlen(cursor) != 0);
    if (!found) {
        return 0;
    }
    if (dirs) {
        *dirs = count;
    }
    if (files) {
        *files = foundFiles;
    }
    return entry;
}

int AtIoFastAlignedJamHeader::FindFile(const char* path, unsigned int* size) {
    char copy[256];
    strcpy(copy, path);
    char* directory;
    char* leaf;
    char* separator = strrchr(copy, '\\');
    if (separator) {
        *separator = 0;
        leaf = separator + 1;
        directory = copy;
    } else {
        leaf = copy;
        directory = 0;
    }
    if (leaf == 0) {
        return -1;
    }
    unsigned int length = strlen(leaf);
    for (unsigned int i = 0; i < length; i++) {
        leaf[i] = (char)toupper(leaf[i]);
    }
    int ext = 0;
    char* dot = strchr(leaf, '.');
    if (dot) {
        *dot = 0;
        ext = m_table.FindExtension(dot + 1);
    }
    int name = m_table.FindName(leaf);
    if (name < 0 || ext < 0) {
        return -1;
    }
    unsigned int dirs;
    unsigned int files;
    const unsigned char* table = FindDirectory(directory, &dirs, &files);
    if (table == 0) {
        return -1;
    }
    const unsigned char* entry = table + dirs * 8;
    for (unsigned int i = 0; i < files; i++) {
        int entryName = AtReadU16(entry);
        int entryExt = entry[2];
        unsigned int offset = AtReadU32(entry + 4);
        unsigned int entrySize = AtReadU32(entry + 8);
        entry += 12;
        if (entryName == name && entryExt == ext) {
            *size = entrySize;
            return (int)offset;
        }
    }
    return -1;
}

int AtIoFastAlignedJamHeader::IsDirectoryMissing(const char* path) {
    return FindDirectory(path, 0, 0) == 0;
}

// Original behaviour preserved: an offset with the top bit set reads as missing.
int AtIoFastAlignedJamHeader::IsFileMissing(const char* path) {
    unsigned int size;
    return FindFile(path, &size) < 0;
}

int AtIoFastAlignedJamHeader::GetEntryType(const char* path, int* type) {
    if (IsFileMissing(path) == 0) {
        *type = kEntryIsFile;
        return 0;
    }
    return 1;
}

